try {
  checkpointText = await readFile(checkpointPath, 'utf8');
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
}
if (checkpointText !== undefined) {
  try {
    const checkpoint = JSON.parse(checkpointText);
    if (!Number.isSafeInteger(checkpoint?.nextLine) || checkpoint.nextLine < 0) {
      throw new Error('Invalid checkpoint nextLine');
    }
    nextLine = checkpoint.nextLine;
  } catch {
    const recoveryPath = join(dirname(checkpointPath), 'recovery', 'checkpoint.bad.json');
    await mkdir(dirname(recoveryPath), { recursive: true });
    // Refuse to overwrite evidence from an earlier recovery.
    try {
      await access(recoveryPath);
      throw new Error(`Recovery evidence already exists: ${recoveryPath}`);
    } catch (error) {
      if (error.code !== 'ENOENT') throw error;
    }
    await rename(checkpointPath, recoveryPath);
    nextLine = 0;
  }
}

